using Application.Common.Exceptions; using Application.Common.Interfaces; using Application.Common.Interfaces.Caching;
using Application.Common.Interfaces.Time; using Application.Features.Premium.Freelancer.RankProtection.DTOs; using Application.Features.Premium.Freelancer.RankProtection.GetRankProtection; using Domain.Entities; using MediatR; using Microsoft.EntityFrameworkCore;
namespace Application.Features.Premium.Freelancer.RankProtection.CancelRankProtection;
public sealed class CancelRankProtectionCommandHandler:IRequestHandler<CancelRankProtectionCommand,RankProtectionDto>{private readonly IApplicationDbContext _context;private readonly IDateTimeService _clock;private readonly ICacheService _cache;public CancelRankProtectionCommandHandler(IApplicationDbContext c,IDateTimeService d,ICacheService cache){_context=c;_clock=d;_cache=cache;}public async Task<RankProtectionDto> Handle(CancelRankProtectionCommand c,CancellationToken ct){var now=_clock.UtcNow;var row=await _context.Set<FreelancerRankProtection>().Where(x=>x.FreelancerProfile.UserId==c.UserId&&x.IsVacationModeEnabled&&x.CancelledAt==null&&x.RankProtectionEndsAt>now).OrderByDescending(x=>x.RankProtectionStartedAt).FirstOrDefaultAsync(ct)??throw new NotFoundException("Active rank protection does not exist.");row.IsVacationModeEnabled=false;row.CancelledAt=now;row.RankProtectionEndsAt=now;await _context.SaveChangesAsync(ct);await _cache.RemoveAsync($"premium:rank-protection:{c.UserId:N}",ct);return RankProtectionMapper.Map(row);}}
